import{_ as e,a as s}from"./chunks/08-editor-cues-word-mode.Dg1IPIEj.js";import{_ as d,o as r,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const E=JSON.parse('{"title":"التوقيت والـ cues والمحاذاة التلقائية","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/timing.md","filePath":"ar/guide/timing.md"}'),i={name:"ar/guide/timing.md"};function n(c,t,l,h,g,p){return r(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="التوقيت-والـ-cues-والمحاذاة-التلقائية" tabindex="-1">التوقيت والـ cues والمحاذاة التلقائية <a class="header-anchor" href="#التوقيت-والـ-cues-والمحاذاة-التلقائية" aria-label="Permalink to &quot;التوقيت والـ cues والمحاذاة التلقائية&quot;">​</a></h1><p>كل ما في الحلقة موقّت نسبةً إلى كلماتك. الـ <strong>cue</strong> هو لحظة بداية سطر النص في تسجيلك، ومنه تُحسب أزمنة الكلمات. تبدأ المشاهد عند الأسطر، وتدخل العناصر عند الكلمات:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scenes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">l3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # the scene starts with line 3</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    elements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bucket</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        enter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;l3:&#39;bucket&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the element enters on the word &quot;bucket&quot;</span></span></code></pre></div><p>أعد تسجيل جملة، وحرّك الـ cue الخاص بها، فتتبعه كل الحركات.</p><h2 id="تعابير-الزمن" tabindex="-1">تعابير الزمن <a class="header-anchor" href="#تعابير-الزمن" aria-label="Permalink to &quot;تعابير الزمن&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الصيغة</th><th>المعنى</th></tr></thead><tbody><tr><td><code>12.5s</code> (أو رقم YAML مثل <code>12.5</code>)</td><td>ثوانٍ مطلقة</td></tr><tr><td><code>l7</code></td><td>بداية السطر <code>l7</code> بحسب الـ cue الخاص به</td></tr><tr><td><code>l7.end</code></td><td>بداية السطر التالي ناقص 0.15 ث</td></tr><tr><td><code>l7:&#39;timeout&#39;</code></td><td>أول كلمة تطابق &quot;timeout&quot; (مع تجاهل علامات الترقيم والتطويل والتشكيل)</td></tr><tr><td><code>l7:&#39;request&#39;#2</code></td><td>المطابقة الثانية</td></tr><tr><td><code>l7.3</code></td><td>الكلمة الرابعة (العد يبدأ من الصفر)</td></tr><tr><td><code>@hook</code> و<code>@hook.end</code></td><td>بداية مشهد ونهايته</td></tr><tr><td>أي مما سبق مع <code>+0.4</code> أو <code>-0.2</code></td><td>إزاحة بالثواني</td></tr></tbody></table><p>ضع بين علامات اقتباس أي نص YAML يحتوي على <code>:</code> أو <code>&#39;</code>، مثل <code>at: &quot;l3:&#39;bucket&#39;&quot;</code>. وفضّل تعابير الكلمات على الثواني المطلقة، فالكلمات تصمد أمام إعادة التسجيل. تجد القائمة الكاملة في <a href="./../authoring.html">كتابة الحلقات</a>. وتعمل الكلمات العربية بالطريقة نفسها: <code>l7:&#39;مرتين&#39;</code>.</p><h2 id="قبل-التسجيل-الـ-cues-التقديرية" tabindex="-1">قبل التسجيل: الـ cues التقديرية <a class="header-anchor" href="#قبل-التسجيل-الـ-cues-التقديرية" aria-label="Permalink to &quot;قبل التسجيل: الـ cues التقديرية&quot;">​</a></h2><p>تحصل كل حلقة جديدة على <strong>cues تقديرية</strong> محسوبة من طول كل سطر (نحو 13 حرفاً في الثانية مع فجوة قصيرة). فتُعرض المعاينة بتوقيت واقعي، ويفحص التحقق سرعة الإلقاء منذ البداية. ولإنشائها استخدم الأمر <code>reelforge cue &lt;id&gt; --draft</code>، أو الزر <strong>Draft cues</strong>، أو الأداة <code>draft_cues</code>.</p><h2 id="نصائح-للتسجيل" tabindex="-1">نصائح للتسجيل <a class="header-anchor" href="#نصائح-للتسجيل" aria-label="Permalink to &quot;نصائح للتسجيل&quot;">​</a></h2><ul><li>سجّل في غرفة هادئة، على بعد 20 إلى 30 سم من الميكروفون. أي معدل عينات مقبول، ويضبط ReelForge مستوى الجهارة تلقائياً (−14 LUFS).</li><li>اقرأ سطراً واحداً في كل نَفَس، واترك وقفة قصيرة (0.3 إلى 0.5 ث) بين الأسطر. فالوقفات تسرّع تحديد الـ cues وتمنح الحركات مساحة.</li><li>ستعيد التسجيل لاحقاً؟ ارفع التسجيل الجديد، وسينبهك ReelForge إلى أن التسجيل تغيّر لتعيد مراجعة الـ cues.</li><li>سجّلت بالهاتف أو في غرفة فيها ضجيج؟ فعّل <strong>Clean up noise</strong> (من إعدادات الحلقة، أو <code>audio: { denoise: true }</code>، أو <code>reelforge render --denoise</code>). يزيل RNNoise الهسيس والطنين وضجيج الغرفة من الصوت قبل المعالجة النهائية (mastering)، وفي الاختبارات خفّض الضجيج بين الجمل بنحو 15 dB دون تغيير مستوى الصوت.</li></ul><h2 id="الـ-cues-التلقائية" tabindex="-1">الـ cues التلقائية <a class="header-anchor" href="#الـ-cues-التلقائية" aria-label="Permalink to &quot;الـ cues التلقائية&quot;">​</a></h2><p>انقر <strong>Auto-mark from voice</strong> في وضع Cues، أو <strong>Auto cues</strong> في لوحة التحكم، أو شغّل <code>reelforge align &lt;id&gt;</code>. يعرف ReelForge النص مسبقاً، فلا يبقى عليه إلا إيجاد بداية كل سطر وكل كلمة في التسجيل. استمع بعدها مرة واحدة وأصلح أي سطر بالسمع (الأسطر الملوّنة بالكهرماني هي التي كانت الثقة فيها أقل). وتُسجَّل النتيجة كخطوة تراجع واحدة (‏**⌘/Ctrl+Z**).</p><p>يوجد محركان:</p><table tabindex="0"><thead><tr><th>المحرك</th><th>المتطلبات</th><th>السرعة (لدقيقة صوت)</th><th>طريقة العمل</th></tr></thead><tbody><tr><td><strong>الوقفات</strong> (افتراضي)</td><td>لا شيء</td><td>~0.05 ث</td><td>يجد الوقفات، ثم يقسم التسجيل على أسطر النص بحيث يناسب طول كل سطر نصّه (برمجة ديناميكية). وتتبع الكلمات المقاطع الصوتية.</td></tr><tr><td><strong>Whisper</strong> (اختياري)</td><td><code>reelforge align --setup</code> مرة واحدة (~180 MB)</td><td>~20 ث على معالج حاسوب محمول</td><td>نموذج كلام يسمع الكلمات، ولا يُستخدم منه إلا <strong>التوقيت</strong> مطابَقاً مع نصك، فلا تؤثر اللهجات ولا المصطلحات الإنجليزية في الجمل العربية. وهو الأفضل لتوقيت الكلمات ومع وجود موسيقى.</td></tr></tbody></table><p>مع تثبيت النماذج الاختيارية، يميّز نموذج صغير لاكتشاف الكلام (Silero VAD، بحجم 2 MB) الكلام عن الموسيقى والأنفاس وضجيج الغرفة. وفي قياسات على كلام مسجّل بأزمنة معروفة، جاء كل سطر بفارق لا يتجاوز 100 ms (بمتوسط 15 ms)، مع موسيقى في الخلفية أو بدونها. أما الكلمات فجاءت بفارق لا يتجاوز 100 ms في نحو 80% من الحالات، لذا راجع بالسمع في وضع الكلمات اللحظات التي تحتاج دقة (مثل ختم يقع على كلمة بعينها).</p><p>يعرض الأمر <code>reelforge align --status</code> ما هو مثبت. وتُحفظ النماذج في مجلد التخزين المؤقت (cache) الخاص بالمستخدم (<code>%LOCALAPPDATA%\\reelforge</code> أو <code>~/Library/Caches/reelforge</code> أو <code>~/.cache/reelforge</code>، ويغيّر <code>$REELFORGE_CACHE</code> مكانها)، ولا تُستخدم أبداً أثناء التصدير. ولا تُستبدل الـ cues التي حددتها يدوياً أبداً إلا بعد تأكيدك (<code>--force</code> في سطر الأوامر).</p><table tabindex="0"><thead><tr><th>الخيار</th><th>المعنى</th></tr></thead><tbody><tr><td><code>--engine &lt;e&gt;</code></td><td><code>auto</code> (‏Whisper إن كان مثبتاً وإلا الوقفات)، أو <code>dsp</code>، أو <code>whisper</code></td></tr><tr><td><code>--model &lt;size&gt;</code></td><td>نموذج Whisper: ‏<code>tiny</code> أو <code>base</code> (الافتراضي) أو <code>small</code></td></tr><tr><td><code>--no-vad</code></td><td>اكتشاف الكلام من طاقة الصوت فقط</td></tr><tr><td><code>--no-words</code></td><td>cues للأسطر فقط</td></tr><tr><td><code>--force</code></td><td>استبدال الـ cues المحددة يدوياً</td></tr><tr><td><code>--dry-run</code></td><td>طباعة النتيجة دون كتابة <code>cues.json</code></td></tr></tbody></table><h2 id="وضع-cues" tabindex="-1">وضع Cues <a class="header-anchor" href="#وضع-cues" aria-label="Permalink to &quot;وضع Cues&quot;">​</a></h2><p>افتح المحرر وانتقل إلى <strong>Cues</strong> (‏<strong>Alt+2</strong>)، أو انقر <strong>Mark cues</strong> في لوحة التحكم. يظهر النص على اليمين، ويظهر مؤشر التشغيل والموجة الصوتية على الخط الزمني.</p><p><img src="`+e+'" alt="وضع Cues"></p><table tabindex="0"><thead><tr><th>المفتاح</th><th>الإجراء</th></tr></thead><tbody><tr><td><strong>Enter</strong> / <strong>K</strong></td><td>تشغيل / إيقاف مؤقت</td></tr><tr><td><strong>1 / 2 / 3</strong></td><td>السرعة 0.5× و0.75× و1× (الأبطأ أدق)</td></tr><tr><td><strong>Space</strong></td><td>تحديد السطر التالي غير المحدد عند مؤشر التشغيل</td></tr><tr><td><strong>النقر على سطر</strong> أو <strong>↑ / ↓</strong></td><td>اختيار سطر لإعادة تحديده (ثم اضغط Space)</td></tr><tr><td><strong>← / →</strong></td><td>تحريك الـ cue المحدد بمقدار 50 ms (و<strong>Shift</strong> بمقدار 10 ms)</td></tr><tr><td><strong>Backspace</strong></td><td>التراجع عن آخر تغيير</td></tr><tr><td><strong>S</strong> / <strong>A</strong></td><td>إلصاق الـ cue المحدد بأقرب بداية للصوت / تبديل الالتصاق التلقائي</td></tr><tr><td><strong>G</strong></td><td>الانتقال إلى الـ cue المحدد</td></tr><tr><td><strong>W</strong></td><td>وضع الكلمات: حدد كل كلمة في السطر المختار بـ Space</td></tr><tr><td><strong>J / L</strong> و**, / .**</td><td>رجوع / تقدم ثانية واحدة، الإطار السابق / التالي</td></tr></tbody></table><p>يُحفظ كل تغيير فوراً في <code>cues.json</code> ويمكن التراجع عنه بـ <strong>⌘/Ctrl+Z</strong>. وتظهر الأسطر التي خرجت عن ترتيبها باللون الأحمر. ويمكنك أيضاً سحب مقطع السطر على مسار <strong>Script</strong> في الخط الزمني، في وضع Edit أو Cues.</p><h2 id="وضع-الكلمات" tabindex="-1">وضع الكلمات <a class="header-anchor" href="#وضع-الكلمات" aria-label="Permalink to &quot;وضع الكلمات&quot;">​</a></h2><p>يقدّر ReelForge افتراضياً بداية كل كلمة من طولها. وللحظات الدقيقة (ختم يقع تماماً على كلمة “twice”)، اختر السطر، واضغط <strong>W</strong>، وشغّل، ثم اضغط <strong>Space</strong> عند كل كلمة.</p><p><img src="'+s+'" alt="وضع الكلمات"></p><h2 id="فحوص-سرعة-الإلقاء" tabindex="-1">فحوص سرعة الإلقاء <a class="header-anchor" href="#فحوص-سرعة-الإلقاء" aria-label="Permalink to &quot;فحوص سرعة الإلقاء&quot;">​</a></h2><p>تنبّه قاعدة التحقق <strong>V-14</strong> عندما يُنطق سطر بأسرع من 3.5 كلمة في الثانية تقريباً (أسرع من أن تُقرأ الترجمة النصية)، وعندما تبدأ الافتتاحية بعد 3 ثوانٍ، وتبلّغ أيضاً عن فترات صمت مدتها 1.5 ث أو أكثر. قسّم الأسطر الطويلة، أو تمهّل عند التسجيل.</p>',28)])])}const b=d(i,[["render",n]]);export{E as __pageData,b as default};
